import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class MyXargs {
    public static void main(String[] args) {
        if (args.length == 0) {
            printUsage();
            return;
        }
        int maxArgs = 100000000;
        String replaceStr = null;
        boolean printCmd = false;
        boolean runOnEmpty = true;
        List<String> command = new ArrayList<>();

        for (int i = 0; i < args.length; i++) {
            switch (args[i]) {
                case "-n":
                    if (i + 1 < args.length) {
                        maxArgs = Integer.parseInt(args[++i]);
                    } else {
                        System.err.println("Error: Missing value for -n option");
                        return;
                    }
                    break;
                case "-I":
                    if (i + 1 < args.length) {
                        replaceStr = args[++i];
                    } else {
                        System.err.println("Error: Missing value for -I option");
                        return;
                    }
                    break;
                case "-t":
                    printCmd = true;
                    break;
                case "-r":
                    runOnEmpty = false;
                    break;
                default:
                    command.add(args[i]);
            }
        }

        if (command.isEmpty()) {
            printUsage();
            return;
        }

        processInput(command, maxArgs, replaceStr, printCmd, runOnEmpty);
    }

    private static void printUsage() {
        System.err.println("Usage: java MyXargs.java [-n num] [-I replace] [-t] [-r] command");
    }

    private static void processInput(List<String> command, int maxArgs, String replaceStr, boolean printCmd, boolean runOnEmpty) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            List<String> inputList = new ArrayList<>();
            boolean hasInput = false;

            while ((line = reader.readLine()) != null && !line.trim().isEmpty()) {
                hasInput = true;
                String[] inputs = line.trim().split("\\s+");
                for (String input : inputs) {
                    inputList.add(sanitizeInput(input));
                }
            }

            if (replaceStr != null) {
                List<String> replacedCommand = replaceCommand(command, replaceStr, String.join(" ", inputList));
                executeCommand(replacedCommand,new ArrayList<>(), printCmd);
            } else if (!inputList.isEmpty()) {
                for (int i = 0; i < inputList.size(); i += maxArgs) {
                    int end = Math.min(inputList.size(), i + maxArgs);
                    List<String> argsSubset = inputList.subList(i, end);
                    executeCommand(command, argsSubset, printCmd);
                }
            }
            if (!hasInput && runOnEmpty) {
                executeCommand(command, new ArrayList<>(), printCmd);
                return;
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static List<String> replaceCommand(List<String> command, String replaceStr, String input) {
        List<String> replacedCommand = new ArrayList<>();
        for (String part : command) {
            replacedCommand.add(part.replace(replaceStr, input));
        }
        return replacedCommand;
    }

    private static String sanitizeInput(String input) {
        return input.replaceAll(";&|><*?$()", "");
    }
// using processBuilder from prof code (fork - alternative) and exception from the java IO.
    private static void executeCommand(List<String> command, List<String> argsList, boolean printCmd) {
        List<String> fullCommand = new ArrayList<>(command);
        fullCommand.addAll(argsList);

        if (printCmd) {
            System.out.println(String.join(" ", fullCommand));
        }

        ProcessBuilder pb = new ProcessBuilder(fullCommand);
        pb.inheritIO();

        try {
            Process process = pb.start();
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}

