import java.io.*;
import java.net.*;
import java.util.Scanner;

public class TCPClient {
    private static final int PORT = 12345;
    private Socket socket;
    private BufferedReader serverInput;
    private DataOutputStream serverOutput;
    private String username;
    private volatile boolean running = true;

    public TCPClient(String hostname, String username) {
        this.username = username;
        try {
            // Connect to the server and creating socket
            this.socket = new Socket(hostname, PORT);
            this.serverInput = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            this.serverOutput = new DataOutputStream(socket.getOutputStream());

            System.out.println("Connected to the server. You can start sending messages.");

            // Start threads for receiving and sending messages
            new Thread(new ServerMessageHandler()).start();
            new Thread(new UserInputHandler()).start();
        } catch (IOException e) {
            System.out.println("Unable to connect to the server. Please check the server address and try again.");
        }
    }
// part 1: 2) Receiving server messages and handling.
    private class ServerMessageHandler implements Runnable {
        public void run() {
            try {
                String message;
                while (running && (message = serverInput.readLine()) != null) {
                    System.out.println(message);
                }
            } catch (IOException e) {
                System.err.println("Disconnected from server.");
            } finally {
                running = false;
                closeConnection();
            }
        }
    }
// part 1: 3) sending user input 
    private class UserInputHandler implements Runnable {
        public void run() {
            Scanner scanner = new Scanner(System.in);
            try {
                // Send username to server for initial setup
                serverOutput.writeBytes(username + "\n");
                serverOutput.flush();

                while (running) {
                    String userMessage = scanner.nextLine();

                    // Check for the quit command
                    if (userMessage.equalsIgnoreCase("/quit")) {
                        running = false;
                        closeConnection();
                        return;
                    }

                    // Send user message to server
                    serverOutput.writeBytes(userMessage + "\n");
                    serverOutput.flush();
                }
            } catch (IOException e) {
                System.out.println("Error sending message to the server.");
            } finally {
                scanner.close();
                closeConnection();
            }
        }
    }
//part1: cleaning up part 1: closing socket
    private void closeConnection() {
        try {
            running = false;
            if (socket != null && !socket.isClosed()) {
                socket.close();
            }
            System.out.println("Connection closed.");
        } catch (IOException e) {
            System.out.println("Error closing the connection.");
        }
    }

    public static void main(String[] args) {
        // part 1: Validate command-line arguments and initialization of connnection.
        if (args.length != 2) {
            System.out.println("Usage: java ./TCPClient.java <hostname> <username>");
            return;
        }

        String hostname = args[0];
        String username = args[1];

        new TCPClient(hostname, username);
    }
}

import java.io.*;
import java.net.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.ArrayList;
import java.util.List;

public class TCPServer {
    //part 2: 1) initialization of socket with port number 12345
    private static final int PORT = 12345;
    private static final ConcurrentHashMap<String, ClientHandler> clientHandlers = new ConcurrentHashMap<>();
    private static volatile boolean running = true;

    public static void main(String[] args) {
        // Register shutdown hook to capture Ctrl-C and stop the server loop
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.out.println("Shutdown signal received.");
            running = false;
        }));

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            int clientId = 0; //using for handling threads
            System.out.println("Listener on port " + PORT);
            System.out.println("Waiting for connections ...");

            while (running) {
                try {
                    Socket clientSocket = serverSocket.accept();
                    // Create and start a new thread for the connected client
                    ClientHandler clientHandler = new ClientHandler(clientSocket, clientId);
                    Thread clientThread = new Thread(clientHandler);
                    clientThread.start();
                    clientId++;
                } catch (IOException e) {
                    if (running) {
                        System.out.println("Error accepting new connection: " + e.getMessage());
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("Server exception: " + e.getMessage());
        }finally {
            System.out.println("Server has been stopped.");
        }
    }

    static class ClientHandler implements Runnable {
        private Socket socket;
        private String username;
        private int clientId;
        private final BufferedReader input;
        private final DataOutputStream output;
        private volatile boolean active = true;
        // initialization of client with socket
        public ClientHandler(Socket socket,int clientId) throws IOException {
            this.socket = socket;
            this.clientId = clientId;
            this.input = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            this.output = new DataOutputStream(socket.getOutputStream());
        }

        @Override
        public void run() {
            try {
                // Read the username from the client
                this.username = input.readLine();
                if (username == null) {
                    closeConnection();
                    return;
                }
                clientHandlers.put(username, this);
                System.out.println("New connection, thread name is " + Thread.currentThread().getName() + 
                                   ", ip is: " + socket.getInetAddress() + 
                                   ", port: " + socket.getPort());
                System.out.println("Adding to list of sockets as " + clientId);

                String message;
                //part2: 3) handling communication and broadcast for active client only.
                while ((message = input.readLine()) != null && active) {
                    System.out.println("client: " + username + ": " + message);
                    broadcast(username + ": " + message+ "\n");
                }

            } catch (IOException e) {
                System.out.println("Error handling client " + username + ": " + e.getMessage());
            } finally {
                closeConnection();
            }
        }
// part2: 4) bradcasting the message
        private void broadcast(String message) {
            clientHandlers.forEach((user, handler) -> {
                if (handler != this ) {
                    try {
                        handler.output.writeBytes(message);
                        handler.output.flush();
                    } catch (IOException e) {
                        System.out.println("Failed to send message to " + user);
                    }
                }
            });
        }
// part2: 6) cleaning up part2 closing connection and printing details to server.
        private void closeConnection() {
            try {
                active = false;
                clientHandlers.remove(username);
                socket.close();
                System.out.println("Host disconnected, ip " + socket.getInetAddress() + ", port " + socket.getPort());
            } catch (IOException e) {
                System.out.println("Error closing connection for user " + username);
            }
        }
    }
}

import java.io.*;
import java.net.*;
import java.nio.file.Files;
import java.util.concurrent.Executors;
import javax.net.ssl.*;

public class WebServer {
    private static final int HTTP_PORT = 8080;
    private static final int HTTPS_PORT = 8443;
    private static final String DEFAULT_CONTENT_TYPE = "application/octet-stream";
    private static final String BASE_DIRECTORY = "./webroot"; // Base directory to serve files
    private static boolean enableHttps = false;

    public static void main(String[] args) {
        final String keystorePath; // Declare as final for lambda compatibility
        final String keystorePassword;

        // Parse optional keystore arguments
        if (args.length == 2) {
            keystorePath = args[0];
            keystorePassword = args[1];
            enableHttps = true;
        } else {
            keystorePath = null;
            keystorePassword = null;
        }

        // Start HTTP server
        Executors.newSingleThreadExecutor().execute(() -> startHttpServer());

        // Start HTTPS server if keystore is provided
        if (enableHttps) {
            Executors.newSingleThreadExecutor().execute(() -> startHttpsServer(keystorePath, keystorePassword));
        } else {
            System.out.println("HTTPS is disabled. Only HTTP server is running.");
        }
    }

    @SuppressWarnings("CallToPrintStackTrace")
    private static void startHttpServer() {
        try (ServerSocket serverSocket = new ServerSocket(HTTP_PORT)) {
            System.out.println("HTTP Server running on port " + HTTP_PORT);
            while (true) {
                Socket clientSocket = serverSocket.accept();
                File baseDir = new File(BASE_DIRECTORY);
            if (!baseDir.exists() || !baseDir.isDirectory()) {
                System.err.println("Base directory " + BASE_DIRECTORY + " does not exist or is not a directory.");
                System.exit(1);
            }
                Executors.newCachedThreadPool().execute(new HttpRequestHandler(clientSocket, false, BASE_DIRECTORY, DEFAULT_CONTENT_TYPE));
            }
        } catch (IOException e) {
            System.err.println("HTTP server exception: " + e.getMessage());
            e.printStackTrace();
        }
    }

    @SuppressWarnings("CallToPrintStackTrace")
    private static void startHttpsServer(String keystorePath, String keystorePassword) {
        try {
            System.setProperty("javax.net.ssl.keyStore", keystorePath);
            System.setProperty("javax.net.ssl.keyStorePassword", keystorePassword);

            SSLServerSocketFactory sslServerSocketFactory = (SSLServerSocketFactory) SSLServerSocketFactory.getDefault();
            try (SSLServerSocket sslServerSocket = (SSLServerSocket) sslServerSocketFactory.createServerSocket(HTTPS_PORT)) {
                System.out.println("HTTPS Server running on port " + HTTPS_PORT);
                while (true) {
                    Socket clientSocket = sslServerSocket.accept();
                    File baseDir = new File(BASE_DIRECTORY);
                    if (!baseDir.exists() || !baseDir.isDirectory()) {
                        System.err.println("Base directory " + BASE_DIRECTORY + " does not exist or is not a directory.");
                        System.exit(1);
                    }
                    Executors.newCachedThreadPool().execute(new HttpRequestHandler(clientSocket, true, BASE_DIRECTORY, DEFAULT_CONTENT_TYPE));
                }
            }
        } catch (IOException e) {
            System.err.println("HTTPS server exception: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

