class HttpRequestHandler implements Runnable {
    private final Socket socket;
    private final boolean isHttps;
    private final String baseDirectory;
    private final String defaultContentType;

    public HttpRequestHandler(Socket socket, boolean isHttps, String baseDirectory, String defaultContentType) {
        this.socket = socket;
        this.isHttps = isHttps;
        this.baseDirectory = baseDirectory;
        this.defaultContentType = defaultContentType;
    }

    @Override
    @SuppressWarnings("CallToPrintStackTrace")
    public void run() {
        try (InputStream is = socket.getInputStream();
             OutputStream os = socket.getOutputStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(is));
             DataOutputStream writer = new DataOutputStream(os)) {

            // Read the HTTP request
            String requestLine = reader.readLine();
            System.out.println("[" + (isHttps ? "HTTPS" : "HTTP") + "] Request: " + requestLine);


            if (requestLine == null || !requestLine.startsWith("GET")) {
                sendError(writer, 405, "Method Not Allowed");
                return;
            }

            // Parse the requested file path
            String[] tokens = requestLine.split(" ");
            if (tokens.length < 2) {
                sendError(writer, 400, "Bad Request");
                return;
            }

            String requestedFile = tokens[1];

            if (requestedFile.equals("/")) {
                requestedFile = "/index.html"; // Default file
            }

            File file = new File(baseDirectory, requestedFile);
            if (!file.getCanonicalPath().startsWith(new File(baseDirectory).getCanonicalPath())) {
                sendError(writer, 403, "Forbidden");
                return;
            }

            if (!file.exists() || file.isDirectory()) {
                sendError(writer, 404, "Not Found");
                return;
            }

            // Serve the file
            String contentType = getContentType(file);
            sendResponse(writer, 200, "OK", contentType, file);

        } catch (IOException e) {
            System.err.println("Request handling exception: " + e.getMessage());
            e.printStackTrace();
        } finally {
            try {
                socket.close();
            } catch (IOException e) {
                System.err.println("Socket closing exception: " + e.getMessage());
            }
        }
    }

    //===================================

    private void sendResponse(DataOutputStream writer, int statusCode, String statusMessage, String contentType, File file) throws IOException {
        byte[] fileBytes = Files.readAllBytes(file.toPath());
        writer.writeBytes("HTTP/1.1 " + statusCode + " " + statusMessage + "\r\n");
        writer.writeBytes("Content-Type: " + contentType + "\r\n");
        writer.writeBytes("Content-Length: " + fileBytes.length + "\r\n");
        writer.writeBytes("\r\n"); // End of headers
        writer.write(fileBytes);
        writer.flush();
    }


    private void sendError(DataOutputStream writer, int statusCode, String statusMessage) throws IOException {
        String errorPage = "<html><body><h1>" + statusCode + " " + statusMessage + "</h1></body></html>";
        writer.writeBytes("HTTP/1.1 " + statusCode + " " + statusMessage + "\r\n");
        writer.writeBytes("Content-Type: text/html\r\n");
        writer.writeBytes("Content-Length: " + errorPage.length() + "\r\n");
        writer.writeBytes("\r\n"); // End of headers
        writer.writeBytes(errorPage);
        writer.flush();
    }

    //================================

    private String getContentType(File file) {
        String fileName = file.getName();
        if (fileName.endsWith(".html")) {
            return "text/html";
        } else if (fileName.endsWith(".jpg") || fileName.endsWith(".jpeg")) {
            return "image/jpeg";
        } else if (fileName.endsWith(".gif")) {
            return "image/gif";
        } else if (fileName.endsWith(".png")) {
            return "image/png";
        } else if (fileName.endsWith(".css")) {
            return "text/css";
        } else if (fileName.endsWith(".js")) {
            return "application/javascript";
        } else {
            return defaultContentType;
        }
    }
}

import java.io.*;
import java.net.*;
import javax.net.ssl.*;

public class webserver {
    public static void main(String[] args) {
        final int httpPort = 8080;
        final int httpsPort = 8443;

        final String keystorePath;
        final String keystorePassword;

        if (args.length == 2) {
            keystorePath = args[0];
            keystorePassword = args[1];
        } else if (args.length > 0) {
            System.err.println("Error: Provide both keystore path and password, or no arguments for HTTP-only mode.");
            System.out.println("Usage: java HTTPServer [keystore.jks keystorePassword]");
            return;
        } else {
            keystorePath = null;
            keystorePassword = null;
        }

        // Start HTTP server
        new Thread(() -> startHttpServer(httpPort)).start();

        // Start HTTPS server if keystore is provided
        if (keystorePath != null && keystorePassword != null) {
            new Thread(() -> startHttpsServer(httpsPort, keystorePath, keystorePassword)).start();
        } else {
            System.out.println("Starting in HTTP-only mode (no keystore provided).");
        }
    }

    // HTTP Server
    private static void startHttpServer(int port) {
        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("HTTP Server running on port " + port);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                HttpRequestHandler requestHandler = new HttpRequestHandler(clientSocket, false);
                new Thread(requestHandler).start();
            }
        } catch (IOException e) {
            System.err.println("HTTP server exception: " + e.getMessage());
        }
    }

    // HTTPS Server
    private static void startHttpsServer(int port, String keystorePath, String keystorePassword) {
        try {
            // Set keystore properties
            System.setProperty("javax.net.ssl.keyStore", keystorePath);
            System.setProperty("javax.net.ssl.keyStorePassword", keystorePassword);

            SSLServerSocketFactory sslFactory = (SSLServerSocketFactory) SSLServerSocketFactory.getDefault();
            SSLServerSocket sslServerSocket = (SSLServerSocket) sslFactory.createServerSocket(port);
            System.out.println("HTTPS Server running on port " + port);

            while (true) {
                Socket clientSocket = sslServerSocket.accept();
                HttpRequestHandler requestHandler = new HttpRequestHandler(clientSocket, true);
                new Thread(requestHandler).start();
            }
        } catch (IOException e) {
            System.err.println("HTTPS server exception: " + e.getMessage());
        }
    }
}

class HttpRequestHandler implements Runnable {
    private final Socket socket;
    private final boolean isHttps;

    public HttpRequestHandler(Socket socket, boolean isHttps) {
        this.socket = socket;
        this.isHttps = isHttps;
    }

    @Override
    public void run() {
        try (InputStream is = socket.getInputStream();
             DataOutputStream os = new DataOutputStream(socket.getOutputStream());
             BufferedReader br = new BufferedReader(new InputStreamReader(is))) {

            // Read the request line
            String requestLine = br.readLine();
            System.out.println((isHttps ? "[HTTPS]" : "[HTTP]") + " Request: " + requestLine);

            if (requestLine != null) {
                String responseBody;

                // Routing logic
                if (requestLine.contains("/hello")) {
                    responseBody = "<html><body><h1>Hello, World!</h1></body></html>";
                } else if (requestLine.contains("/goodbye")) {
                    responseBody = "<html><body><h1>Goodbye, World!</h1></body></html>";
                } else {
                    responseBody = "<html><body><h1>404 - Not Found</h1></body></html>";
                }

                // Send the response
                String response = """
                                  HTTP/1.1 200 OK\r
                                  Content-Type: text/html\r
                                  Content-Length: """ + responseBody.length() + "\r\n" +
                                  "\r\n" +
                                  responseBody;
                os.writeBytes(response);
            }

        } catch (IOException e) {
            System.err.println("Request handling exception: " + e.getMessage());
        } finally {
            try {
                socket.close();
            } catch (IOException e) {
                System.err.println("Socket closing exception: " + e.getMessage());
            }
        }
    }
}
